        '2026-08': { month: 'Tháng 08/2026', key: '2026-08', count: 0, suppliers: [], orders: [], notes: 'Hoàng Hà Ceramic Calacatta & Hợp đồng đồ rời Sofa xưởng Khánh T8+T9 (11.65M lãi gộp)' },
